import assert from 'node:assert/strict'
import test from 'node:test'
import { mkdtemp, rm, readFile, readdir } from 'node:fs/promises'
import { join } from 'node:path'; import { tmpdir } from 'node:os'
import { createFreshKnowledgeBaseV04 } from '../../../knowledge/storage/index.ts'; import { KnowledgeBaseRegistry } from '../../../knowledge/registry/registry.ts'; import { readCanonicalV04Assets } from '../../../knowledge/storage/canonical-v04-loader.ts'
import { runIndustryDeepResearch as executeIndustryDeepResearch } from '../../../workflows/industry-deep-research/index.ts'; import type { IndustryDeepResearchInput, IndustryAcquisitionWave } from '../../../workflows/industry-deep-research/contracts.ts'; import { INDUSTRY_MODULES } from '../../../skills/industry-research/index.ts'; import type { ReasoningExecutor } from '../../../plugins/reasoning/contracts.ts'; import { sha256 } from '../../../plugins/research-acquisition/hash.ts'; import { getCanonicalResearchSkill } from '../../../app/services/research-skill-catalog.ts'; import { createIndustryWorkflowResolverFixture } from '../../support/industry-workflow-resolver-fixture.ts'
import { validateKnowledgeV04Objects } from '../../../knowledge/validation/v04-validator.ts'
const source = (id: string) => { const content = `Official industry supplier capacity evidence for ${id}.`; return { candidate: { candidateId: id, kind: 'official_disclosure' as const, tier: 1 as const, title: id, provider: 'fixture', publishedAt: '2026-09-01' }, retrievedAt: '2026-09-01', title: id, content, contentHash: sha256(content), publisher: 'Fixture', rights: { accessScope: 'public' as const, retentionAllowed: true, aiProcessingAllowed: true, derivativeKnowledgeAllowed: true, redistributionAllowed: false } } }
const design = { definitionHypothesis: 'Fixture Industry', targetKind: 'industry', scope: { included: ['fixture'], excluded: ['theme'] }, moduleQuestions: Object.fromEntries(INDUSTRY_MODULES.map((m) => [m, m])), keyMetrics: ['capacity'], evidenceRequirements: ['official'], searchTerms: ['fixture'], knownGaps: [], verificationCandidates: [] }
const allTitles = ['Executive Industry View','Industry Scope & Definition','Market Size & Growth','Demand Structure & Drivers','Supply, Capacity & Utilization','Supply-Demand Balance & Pricing','Industry Chain Map','Value Capture & Industry Economics','Competitive Landscape','Technology & Product Roadmap','Company Mapping & Exposure','Catalysts','Risks & Invalidation Conditions','Key Metrics & Monitoring','Research Gaps & Alternative Views','Methodology & Provenance']
const emptyCompetitionTable = { columns: [{ id: 'company', label: 'Company', role: 'company' }, { id: 'products', label: 'Main products', role: 'main_products' }, { id: 'market_cap', label: 'Market cap', role: 'market_cap' }, { id: 'annual_revenue', label: 'Annual revenue', role: 'annual_revenue' }], rows: [] }
const miitDefinitionSource = { candidate: { candidateId: 'miit-definition-anchor', kind: 'official_disclosure' as const, tier: 1 as const, title: '印制电路板行业规范条件', provider: 'miit', publishedAt: '2013-09-17T00:00:00.000Z', metadata: { anchor: true, moduleHints: ['industry_definition'] } }, retrievedAt: '2026-09-14', title: '印制电路板行业规范条件', content: 'PCB production enterprises are in scope; dedicated equipment and dedicated material manufacturing are outside the management scope.', contentHash: sha256('PCB production enterprises are in scope; dedicated equipment and dedicated material manufacturing are outside the management scope.'), publisher: 'Ministry of Industry and Information Technology', rights: { accessScope: 'public' as const, retentionAllowed: true, aiProcessingAllowed: true, derivativeKnowledgeAllowed: true, redistributionAllowed: false } }
type WorkflowFixtureInput = Omit<IndustryDeepResearchInput, 'dataResolverFactory' | 'skillDataRequirements'> & Partial<Pick<IndustryDeepResearchInput, 'dataResolverFactory' | 'skillDataRequirements'>> & { readonly acquisitionWave?: IndustryAcquisitionWave }
function runIndustryDeepResearch(input: WorkflowFixtureInput) { const { acquisitionWave, ...workflowInput } = input; const now = input.now ?? (() => new Date().toISOString()); return executeIndustryDeepResearch({ ...workflowInput, dataResolverFactory: input.dataResolverFactory ?? createIndustryWorkflowResolverFixture(acquisitionWave ?? (async () => []), now), skillDataRequirements: input.skillDataRequirements ?? getCanonicalResearchSkill('industry_supply_demand_cycle')!.dataRequirements }) }
async function fixtureRun(overrides: Partial<WorkflowFixtureInput> = {}) { const root = await mkdtemp(join(tmpdir(), 'rhl-industry-matrix-')); const reports = await mkdtemp(join(tmpdir(), 'rhl-industry-matrix-reports-')); await createFreshKnowledgeBaseV04(root, { knowledgeBaseId: `kb-${Date.now()}-${Math.random().toString(16).slice(2)}`, now: '2026-09-01T00:00:00.000Z' }); const handle = await new KnowledgeBaseRegistry().mount(root); const input = { workflowRunId: `matrix-${Math.random().toString(16).slice(2)}`, handle, target: { name: 'Fixture Industry' }, reportRoot: reports, reasoningExecutor: exec(), acquisitionWave: async ({ wave }: { wave: 1 | 2 }) => wave === 1 ? [source('s1')] : [], now: () => '2026-09-02T00:00:00.000Z', ...overrides } as WorkflowFixtureInput; const result = await runIndustryDeepResearch(input); return { root, reports, handle, result } }
async function cleanup(x: { root: string; reports: string }) { await rm(x.root, { recursive: true, force: true }); await rm(x.reports, { recursive: true, force: true }) }
function proposalExecutor(proposals: readonly Record<string, unknown>[]) { return { capabilities: () => ({ maxContextTokens: 10000, maxOutputTokens: 10000, structuredOutputSupport: true, maxConcurrency: 8 }), execute: async (r: any) => { const op = String(r.operation); if (op === 'industry_research_design') return { operation: r.operation, output: design }; if (op === 'industry_module_analysis') { const x = r.input as { module: string; evidence: Array<{ evidenceId: string }> }; const ps = x.module === 'company_mapping' ? proposals.map((p) => p.kind === 'entity' && p.entityType === 'company' && !p.structuredValue ? { ...p, sourceCandidateIds: ['evidence-s1'], structuredValue: { ticker: '000001', exchange: 'SZSE' } } : p) : []; const ids = x.evidence.map((e) => e.evidenceId); return { operation: r.operation, output: { module: x.module, status: 'supported', analysis: 'fixture', evidenceIds: ids, proposals: ps, gaps: [], reportMaterial: { markdown: 'fixture module', evidenceIds: ids, proposalIds: ps.map((p) => p.proposalId), relationProposalIds: ps.filter((p) => p.kind === 'relation').map((p) => p.proposalId) }, ...(x.module === 'competitive_landscape' ? { competitionTable: { columns: [{ id: 'company', label: 'Company', role: 'company' }, { id: 'products', label: 'Main products', role: 'main_products' }, { id: 'market_cap', label: 'Market cap', role: 'market_cap' }, { id: 'annual_revenue', label: 'Annual revenue', role: 'annual_revenue' }], rows: [] } } : {}) } } } const i = r.input as { evidence: Array<{ evidenceId: string }> }; const ids = i.evidence.map((e) => e.evidenceId); return { operation: r.operation, output: { executiveView: 'fixture view', analysis: 'fixture synthesis', evidenceIds: ids, proposals: [], gaps: [], alternativeViews: ['fixture alternative'], reportMaterial: { markdown: 'fixture synthesis', evidenceIds: ids, proposalIds: [] } } } } } }
function exec(): ReasoningExecutor {
  return {
    capabilities: () => ({ maxContextTokens: 10000, maxOutputTokens: 10000, structuredOutputSupport: true, maxConcurrency: 8 }),
    execute: async (r) => {
      const op = String(r.operation)
      if (op === 'industry_research_design') return { operation: r.operation, output: design }
      if (op === 'industry_module_analysis') {
        const x = r.input as { module: string }
        return { operation: r.operation, output: {
          module: x.module, status: 'supported', analysis: 'Bounded evidence analysis.', evidenceIds: ['evidence-s1'], proposals: [], gaps: [],
          reportMaterial: { markdown: 'Evidence-backed module.', evidenceIds: ['evidence-s1'], proposalIds: [] },
          ...(x.module === 'competitive_landscape' ? { competitionTable: {
            columns: [{ id: 'company', label: 'Company', role: 'company' }, { id: 'products', label: 'Main products', role: 'main_products' }, { id: 'market_cap', label: 'Market cap', role: 'market_cap' }, { id: 'annual_revenue', label: 'Annual revenue', role: 'annual_revenue' }], rows: [],
          } } : {}),
        } }
      }
      return { operation: r.operation, output: { executiveView: 'Executive view.', analysis: 'Synthesis.', evidenceIds: ['evidence-s1'], proposals: [], gaps: [], alternativeViews: ['Alternative view.'], reportMaterial: { markdown: 'Synthesis.', evidenceIds: ['evidence-s1'], proposalIds: [] } } }
    },
  }
}
test('Industry workflow rejects disabled structured Knowledge before reading or acquiring', async () => { const root = await mkdtemp(join(tmpdir(), 'rhl-industry-structured-off-')); const reports = await mkdtemp(join(tmpdir(), 'rhl-industry-structured-off-reports-')); try { await createFreshKnowledgeBaseV04(root, { knowledgeBaseId: 'kb-industry-structured-off', now: '2026-09-01T00:00:00.000Z' }); const result = await runIndustryDeepResearch({ workflowRunId: 'industry-structured-off', handle: await new KnowledgeBaseRegistry().mount(root), target: { name: 'Fixture Industry' }, reportRoot: reports, reasoningExecutor: exec(), useStructuredKnowledge: false, acquisitionWave: async () => { throw new Error('acquisition must not run') } }); assert.equal(result.status, 'blocked'); assert.equal(result.gatewaySubmitCount, 0); assert.equal(result.acquisitionWaves, 0); assert.match(result.errors.join('; '), /structured Knowledge context/i); assert.deepEqual(await readdir(reports), []) } finally { await rm(root, { recursive: true, force: true }); await rm(reports, { recursive: true, force: true }) } })
test('Industry workflow runs eight modules, skips Wave 2 on no-gap flow, and persists sixteen sections', async () => { const root = await mkdtemp(join(tmpdir(), 'rhl-industry-')); const reports = await mkdtemp(join(tmpdir(), 'rhl-industry-reports-')); try { await createFreshKnowledgeBaseV04(root, { knowledgeBaseId: 'kb-industry', now: '2026-09-01T00:00:00.000Z' }); let waves = 0; const result = await runIndustryDeepResearch({ workflowRunId: 'industry-run', handle: await new KnowledgeBaseRegistry().mount(root), target: { name: 'Fixture Industry' }, reportRoot: reports, reasoningExecutor: exec(), acquisitionWave: async ({ wave }) => { waves++; return wave === 1 ? [source('s1')] : [] }, now: () => '2026-09-02T00:00:00.000Z' }); assert.equal(result.status, 'completed', result.errors.join('; ')); assert.equal(waves, 1); assert.equal(result.modules.length, 8); assert.equal(result.gatewaySubmitCount, 1); assert.equal(result.acquisitionWaves, 1); const json = JSON.parse(await readFile(`${result.report?.outputPath}.json`, 'utf8')); assert.equal(json.sections.length, 16) } finally { await rm(root, { recursive: true, force: true }); await rm(reports, { recursive: true, force: true }) } })

test('Industry rerun preserves canonical refs and exposes updated IDs with the committed revision', async () => {
  const root = await mkdtemp(join(tmpdir(), 'rhl-industry-refresh-'))
  const reports = await mkdtemp(join(tmpdir(), 'rhl-industry-refresh-reports-'))
  try {
    await createFreshKnowledgeBaseV04(root, { knowledgeBaseId: 'kb-industry-refresh', now: '2026-09-01T00:00:00.000Z' })
    let body = 'Official industry supplier capacity evidence.'
    const evidence = () => ({ ...source('s1'), canonicalUrl: 'https://fixture.test/source/s1', candidate: { ...source('s1').candidate, url: 'https://fixture.test/source/s1' }, content: body, contentHash: sha256(body) })
    const reasoning = proposalExecutor([
      { proposalId: 'refresh-company', kind: 'entity', subjectKey: 'refresh-company', entityType: 'company', entityName: 'Refresh Fixture Company' },
      { proposalId: 'refresh-exposure', kind: 'relation', subjectKey: 'refresh-company', targetKey: 'industry', relationType: 'business_exposure', sourceCandidateIds: ['evidence-s1'] },
      { proposalId: 'refresh-claim', kind: 'claim', subjectKey: 'refresh-company', claimType: 'fact', statement: 'The company operates in the fixture industry.', sourceCandidateIds: ['evidence-s1'] },
    ]) as unknown as ReasoningExecutor
    const originalHandle = await new KnowledgeBaseRegistry().mount(root)
    const run = (workflowRunId: string, handle: Awaited<ReturnType<KnowledgeBaseRegistry['mount']>>, canonicalRef?: string) => runIndustryDeepResearch({ workflowRunId, handle, target: { name: 'Fixture Industry', ...(canonicalRef === undefined ? {} : { canonicalRef }) }, reportRoot: reports, reasoningExecutor: reasoning, acquisitionWave: async () => [evidence()], now: () => '2026-09-02T00:00:00.000Z' })
    const first = await run('industry-refresh-1', originalHandle)
    assert.equal(first.status, 'completed', first.errors.join('; '))
    assert.equal(first.knowledgeBaseRevision, 1)
    assert.ok(first.createdIds.includes(first.sourceRefs['evidence-s1']))
    assert.deepEqual(first.committedIds, [...first.createdIds, ...first.updatedIds])

    body = 'Official industry supplier capacity evidence with an updated observation.'
    const second = await run('industry-refresh-2', await new KnowledgeBaseRegistry().mount(root), first.entityRefs.industry)
    assert.equal(second.status, 'completed', second.errors.join('; '))
    assert.equal(second.knowledgeBaseRevision, 2)
    assert.deepEqual(second.createdIds, [])
    assert.ok(second.updatedIds.includes(first.sourceRefs['evidence-s1']))
    assert.equal(second.sourceRefs['evidence-s1'], first.sourceRefs['evidence-s1'])
    assert.deepEqual(second.committedIds, [...second.createdIds, ...second.updatedIds])

  } finally {
    await rm(root, { recursive: true, force: true })
    await rm(reports, { recursive: true, force: true })
  }
})

test('competitive landscape maps the Skill table through Gateway and persists the canonical Module with evidence refs', async () => {
  const root = await mkdtemp(join(tmpdir(), 'rhl-industry-competition-'))
  const reports = await mkdtemp(join(tmpdir(), 'rhl-industry-competition-reports-'))
  try {
    await createFreshKnowledgeBaseV04(root, { knowledgeBaseId: 'kb-industry-competition', now: '2026-09-01T00:00:00.000Z' })
    const reasoning: ReasoningExecutor = { ...exec(), execute: async (request) => {
      if (String(request.operation) === 'industry_research_design') return { operation: request.operation, output: design }
      if (String(request.operation) === 'industry_module_analysis') {
        const input = request.input as { module: string; evidence: Array<{ evidenceId: string }> }
        const evidenceIds = input.evidence.map((item) => item.evidenceId)
        const proposals = input.module === 'competitive_landscape' ? [
          { proposalId: 'company-a', kind: 'entity', subjectKey: 'company-a', entityType: 'company', entityName: 'Fixture Corp', sourceCandidateIds: evidenceIds, structuredValue: { ticker: '000001', exchange: 'SZSE' } },
          { proposalId: 'exposure-a', kind: 'relation', subjectKey: 'company-a', targetKey: 'industry', relationType: 'business_exposure', sourceCandidateIds: evidenceIds },
          { proposalId: 'products-a', kind: 'claim', subjectKey: 'company-a', claimType: 'fact', statement: 'Fixture Corp sells core products.', sourceCandidateIds: evidenceIds },
          { proposalId: 'market-cap-a', kind: 'claim', subjectKey: 'company-a', claimType: 'fact', statement: 'Fixture Corp market cap as of date.', sourceCandidateIds: evidenceIds, temporal: { asOf: '2026-09-01' }, structuredValue: { metric: 'metric:market_cap', value: 100, unit: 'CNY', comparator: 'eq', period: '2026-09-01' } },
          { proposalId: 'revenue-a', kind: 'claim', subjectKey: 'company-a', claimType: 'fact', statement: 'Fixture Corp latest annual revenue.', sourceCandidateIds: evidenceIds, structuredValue: { metric: 'metric:revenue', value: 20, unit: 'CNY', comparator: 'eq', fiscalPeriod: 'FY2025' } },
        ] : []
        const competitionTable = input.module === 'competitive_landscape' ? {
          columns: [
            { id: 'company', label: '公司', role: 'company' },
            { id: 'products', label: '主要产品', role: 'main_products' },
            { id: 'market_cap', label: '最新市值', role: 'market_cap' },
            { id: 'annual_revenue', label: '最新年报营收', role: 'annual_revenue' },
          ],
          rows: [{ companyKey: 'company-a', businessExposureProposalId: 'exposure-a', cells: [
            { columnId: 'products', status: 'available', displayValue: 'Core products', knowledgeProposalIds: ['products-a'] },
            { columnId: 'market_cap', status: 'available', displayValue: '100', knowledgeProposalIds: ['market-cap-a'], asOf: '2026-09-01', unit: 'CNY', currency: 'CNY' },
            { columnId: 'annual_revenue', status: 'available', displayValue: '20', knowledgeProposalIds: ['revenue-a'], fiscalYear: 2025, unit: 'CNY', currency: 'CNY' },
          ] }],
        } : undefined
        return { operation: request.operation, output: { module: input.module, status: 'supported', analysis: 'Competitive overview.', evidenceIds, proposals, gaps: [], reportMaterial: { markdown: 'Competitive overview.', evidenceIds, proposalIds: proposals.map((proposal) => proposal.proposalId), relationProposalIds: proposals.filter((proposal) => proposal.kind === 'relation').map((proposal) => proposal.proposalId) }, ...(competitionTable ? { competitionTable } : {}) } }
      }
      return { operation: request.operation, output: { executiveView: 'View.', analysis: 'Synthesis.', evidenceIds: ['evidence-s1'], proposals: [], gaps: [], alternativeViews: [], reportMaterial: { markdown: 'Synthesis.', evidenceIds: ['evidence-s1'], proposalIds: [] } } }
    } }
    const result = await runIndustryDeepResearch({ workflowRunId: 'competition-module-e2e', handle: await new KnowledgeBaseRegistry().mount(root), target: { name: 'Fixture Industry' }, reportRoot: reports, reasoningExecutor: reasoning, acquisitionWave: async () => [source('s1')], now: () => '2026-09-02T00:00:00.000Z' })
    assert.equal(result.status, 'completed', JSON.stringify({ errors: result.errors, entityRefs: result.entityRefs, relationRefs: result.relationRefs, diagnostics: result.diagnostics }))
    assert.equal(result.gatewaySubmitCount, 1)
    const persisted = (await readCanonicalV04Assets(root)).objects.map((entry) => entry.value as any).find((value) => value.type === 'competition')
    assert.ok(persisted)
    assert.equal(persisted.schemaId, 'competition-landscape-v1')
    assert.deepEqual(persisted.columns.map((column: any) => column.role), ['company', 'main_products', 'market_cap', 'annual_revenue'])
    assert.equal(persisted.rows.length, 1)
    assert.equal(persisted.rows[0].cells.market_cap.asOf, '2026-09-01')
    assert.equal(persisted.rows[0].cells.annual_revenue.fiscalYear, 2025)
    assert.ok(persisted.rows[0].cells.market_cap.knowledgeRefs[0].startsWith('claim:'))
    const validation = validateKnowledgeV04Objects((await readCanonicalV04Assets(root)).objects.map((entry) => entry.value))
    assert.equal(validation.status, 'passed', JSON.stringify(validation.errors))
  } finally { await rm(root, { recursive: true, force: true }); await rm(reports, { recursive: true, force: true }) }
})

test('Industry workflow repairs synthesis once and reaches Gateway and sixteen-section persistence', async () => { const x = await fixtureRun({
  reasoningExecutor: (() => { let synthesisCalls = 0; const calls: string[] = []; const base = exec(); return { capabilities: base.capabilities, execute: async (r) => { calls.push(String(r.operation)); if (String(r.operation) === 'industry_cross_module_synthesis') { synthesisCalls++; if (synthesisCalls === 1) return { operation: r.operation, output: { executiveView: 'bad', analysis: 'bad', evidenceIds: ['evidence-s1'], proposals: [], gaps: [], alternativeViews: [], reportMaterial: { markdown: 'bad', evidenceIds: ['evidence-s1'], proposalIds: ['unknown'] } } }; return { operation: r.operation, output: { executiveView: 'repaired', analysis: 'repaired', evidenceIds: ['evidence-s1'], proposals: [{ proposalId: 'synthesis-claim', kind: 'claim', subjectKey: 'industry', claimType: 'fact', statement: 'A conservative evidence-backed synthesis claim.', sourceCandidateIds: ['evidence-s1'] }], gaps: [], alternativeViews: [], reportMaterial: { markdown: 'repaired', evidenceIds: ['evidence-s1'], proposalIds: ['synthesis-claim'] } } }; } return base.execute(r) } }; })(),
}); try { assert.equal(x.result.status, 'completed', x.result.errors.join('; ')); assert.equal(x.result.gatewaySubmitCount, 1); assert.equal(x.result.knowledgeBaseRevision, 1); assert.equal(x.result.moduleCallCounts.industry_definition, 1); assert.equal(Object.values(x.result.moduleCallCounts).reduce((a, b) => a + b, 0), 8); assert.equal(JSON.parse(await readFile(`${x.result.report?.outputPath}.json`, 'utf8')).sections.length, 16) } finally { await cleanup(x) } })

test('Industry workflow repairs an incompatible structured value before one Gateway submission and Schema 0.4 validation', async () => {
  let companyCalls = 0
  const product = { proposalId: 'product', kind: 'entity', subjectKey: 'product', entityType: 'product', entityName: 'Fixture Product' }
  const claim = (structuredValue: Record<string, unknown>) => ({ proposalId: 'metric', kind: 'claim', subjectKey: 'product', claimType: 'fact', statement: 'Capacity was measured for the period.', sourceCandidateIds: ['evidence-s1'], structuredValue })
  const reasoning: ReasoningExecutor = { ...exec(), execute: async (r) => {
    if (String(r.operation) === 'industry_module_analysis') {
      const input = r.input as { module: string; evidence: Array<{ evidenceId: string }> }
      const proposals = input.module === 'company_mapping' ? [product, claim(companyCalls++ === 0 ? { metric: 'capacity', value: 10, unit: 'GW', comparator: 'eq', period: '2026', geography: 'US' } : { metric: 'capacity', value: 10, unit: 'GW', comparator: 'eq', period: '2026', semanticKey: 'capacity' })] : []
      return { operation: r.operation, output: { module: input.module, status: 'supported', analysis: 'fixture', evidenceIds: input.evidence.map((x) => x.evidenceId), proposals, gaps: [], reportMaterial: { markdown: 'fixture', evidenceIds: input.evidence.map((x) => x.evidenceId), proposalIds: proposals.map((x) => x.proposalId) } } }
    }
    return exec().execute(r)
  } }
  const x = await fixtureRun({ reasoningExecutor: reasoning })
  try {
    assert.equal(x.result.status, 'completed', x.result.errors.join('; ')); assert.equal(companyCalls, 2); assert.equal(x.result.gatewaySubmitCount, 1); assert.equal(x.result.knowledgeBaseRevision, 1); assert.equal(JSON.parse(await readFile(`${x.result.report?.outputPath}.json`, 'utf8')).sections.length, 16)
    const validation = validateKnowledgeV04Objects((await readCanonicalV04Assets(x.root)).objects.map((x) => x.value))
    assert.equal(validation.status, 'passed', JSON.stringify(validation.errors)); assert.equal(validation.errors.some((e) => e.code === 'V04_STRUCTURED_VALUE'), false)
    const persisted = (await canonicalValues(x.root)).find((value) => value.id === x.result.claimRefs.metric) as any
    assert.deepEqual(persisted.structuredValue, { metric: 'capacity', value: 10, unit: 'GW', comparator: 'eq', period: '2026', semanticKey: 'capacity' })
  } finally { await cleanup(x) }
})
test('Industry workflow fails closed for Theme diagnosis and cancellation', async () => { const root = await mkdtemp(join(tmpdir(), 'rhl-industry-block-')); try { await createFreshKnowledgeBaseV04(root, { knowledgeBaseId: 'kb-industry-block', now: '2026-09-01T00:00:00.000Z' }); const themeExec: ReasoningExecutor = { ...exec(), execute: async (r) => String(r.operation) === 'industry_research_design' ? { operation: r.operation, output: { ...design, targetKind: 'theme' } } : (await exec().execute(r)) }; const result = await runIndustryDeepResearch({ workflowRunId: 'theme-run', handle: await new KnowledgeBaseRegistry().mount(root), target: { name: 'AI Infrastructure' }, reportRoot: root, reasoningExecutor: themeExec, acquisitionWave: async () => { throw new Error('must not acquire') } }); assert.equal(result.status, 'blocked'); assert.equal(result.gatewaySubmitCount, 0); const controller = new AbortController(); controller.abort(); const cancelled = await runIndustryDeepResearch({ workflowRunId: 'cancel-run', handle: await new KnowledgeBaseRegistry().mount(root), target: { name: 'Fixture' }, reportRoot: root, reasoningExecutor: exec(), acquisitionWave: async () => [], signal: controller.signal }); assert.equal(cancelled.status, 'cancelled') } finally { await rm(root, { recursive: true, force: true }) } })

