test('Workflow routes hinted evidence, bounds module evidence, and bounds Existing Knowledge to 80', async () => { const seen: Array<{ module: string; evidence: string[]; knowledge: number }> = []; const bigKnowledge = Array.from({ length: 100 }, (_, i) => ({ id: `knowledge-${i}` })); const hinted = (id: string, module: string) => ({ ...source(id), candidate: { ...source(id).candidate, metadata: { module } }, title: `${module} only` }); const x = await fixtureRun({ existingKnowledge: bigKnowledge, maxEvidencePerModule: 1, acquisitionWave: async () => [hinted('supply', 'supply_demand_analysis'), hinted('chain', 'industry_chain_analysis'), { ...source('unrelated'), candidate: { ...source('unrelated').candidate, metadata: { module: 'unrelated' } } }], reasoningExecutor: { ...exec(), execute: async (r) => { if (String(r.operation) === 'industry_module_analysis') { const i = r.input as { module: string; evidence: Array<{ evidenceId: string }>; existingKnowledge: unknown[] }; seen.push({ module: i.module, evidence: i.evidence.map((e) => e.evidenceId), knowledge: i.existingKnowledge.length }); const ids = i.evidence.map((e) => e.evidenceId); return { operation: r.operation, output: { module: i.module, status: 'supported', analysis: 'bounded', evidenceIds: ids, proposals: [], gaps: [], reportMaterial: { markdown: 'bounded', evidenceIds: ids, proposalIds: [] } } } } if (String(r.operation) === 'industry_cross_module_synthesis') { const i = r.input as { evidence: Array<{ evidenceId: string }> }; const ids = i.evidence.map((e) => e.evidenceId); return { operation: r.operation, output: { executiveView: 'bounded', analysis: 'bounded', evidenceIds: ids, proposals: [], gaps: [], alternativeViews: ['bounded alternative'], reportMaterial: { markdown: 'bounded', evidenceIds: ids, proposalIds: [] } } } } else if (String(r.operation) === 'industry_research_design') assert.equal((r.input as { existingKnowledge: unknown[] }).existingKnowledge.length, 80); return exec().execute(r) } } }); try { assert.equal(x.result.status, 'completed', x.result.errors.join('; ')); for (const i of seen) { assert.ok(i.evidence.length <= 1); assert.equal(i.knowledge, 80) } assert.deepEqual(seen.find((i) => i.module === 'supply_demand_analysis')?.evidence, ['evidence-supply']); assert.deepEqual(seen.find((i) => i.module === 'industry_chain_analysis')?.evidence, ['evidence-chain']); assert.deepEqual(seen.find((i) => i.module === 'risk_analysis')?.evidence, []) } finally { await cleanup(x) } })

