test('Workflow report material proves validated catalyst and metric inputs, plus independent gaps and alternative views', async () => { const proposals = [{ proposalId: 'catalyst', kind: 'claim', subjectKey: 'industry', claimType: 'catalyst', statement: 'Policy approval is a validated catalyst.', sourceCandidateIds: ['evidence-s1'] }, { proposalId: 'metric', kind: 'claim', subjectKey: 'industry', claimType: 'fact', statement: 'Capacity utilization is monitored.', sourceCandidateIds: ['evidence-s1'], structuredValue: { metric: 'utilization', value: 80, unit: '%', comparator: 'eq', period: '2026' } }]; const x = await fixtureRun({ reasoningExecutor: { ...proposalExecutor(proposals), execute: async (r: any) => { if (String(r.operation) === 'industry_module_analysis') { const i = r.input as { module: string; evidence: Array<{ evidenceId: string }> }; const ids = i.evidence.map((e) => e.evidenceId); const ps = i.module === 'company_mapping' ? proposals : []; return { operation: r.operation, output: { module: i.module, status: 'partial', analysis: 'material', evidenceIds: ids, proposals: ps, gaps: [{ gapId: `${i.module}-gap`, module: i.module, question: `${i.module} unresolved`, reason: 'fixture', actionable: true }], reportMaterial: { markdown: i.module === 'supply_demand_analysis' ? 'capacity utilization balance' : 'material', evidenceIds: ids, proposalIds: ps.map((p) => p.proposalId), relationProposalIds: [] } } } } if (String(r.operation) === 'industry_cross_module_synthesis') { const i = r.input as { evidence: Array<{ evidenceId: string }> }; const ids = i.evidence.map((e) => e.evidenceId); return { operation: r.operation, output: { executiveView: 'view', analysis: 'analysis', evidenceIds: ids, proposals: [], gaps: [{ gapId: 'synthesis-gap', module: 'risk_analysis', question: 'synthesis unresolved', reason: 'fixture', actionable: true }], alternativeViews: ['Alternative view survives the synthesis gap.'], reportMaterial: { markdown: 'synthesis', evidenceIds: ids, proposalIds: [] } } } } return exec().execute(r) } } }); try { assert.equal(x.result.status, 'completed', x.result.errors.join('; ')); const report = JSON.parse(await readFile(`${x.result.report?.outputPath}.json`, 'utf8')); assert.match(report.sections[11].markdown, /Policy approval/); assert.match(report.sections[13].markdown, /utilization/); assert.match(report.sections[14].markdown, /unresolved|Alternative view/) } finally { await cleanup(x) } })

async function canonicalValues(root: string) { return (await readCanonicalV04Assets(root)).objects.map((x) => x.value as unknown as Record<string, unknown>) }
async function directGateRun(proposals: readonly Record<string, unknown>[], overrides: Partial<Parameters<typeof runIndustryDeepResearch>[0]> = {}) { return fixtureRun({ reasoningExecutor: proposalExecutor(proposals), ...(proposals.some((p) => p.proposalId === 'weak-supplier') ? { maxSources: 1 } : {}), ...overrides }) }
function baseEntities() { return [{ proposalId: 'product', kind: 'entity', subjectKey: 'product', entityType: 'product', entityName: 'Fixture Product' }, { proposalId: 'company', kind: 'entity', subjectKey: 'company', entityType: 'company', entityName: 'Fixture Company' }] }
function validClaim(proposalId: string, subjectKey = 'product') { return { proposalId, kind: 'claim', subjectKey, claimType: 'fact', statement: `Valid ${proposalId}`, sourceCandidateIds: ['evidence-s1'] } }
async function assertNoCanonicalSemantics(x: { root: string }, patterns: readonly RegExp[]) { const values = await canonicalValues(x.root); for (const p of patterns) assert.equal(values.some((v) => p.test(JSON.stringify(v))), false, `unexpected canonical object matching ${p}`); return values }

test('Workflow direct durable gate rejects duplicate local proposal IDs in full while preserving unrelated candidates', async () => { const proposals = [...baseEntities(), { proposalId: 'duplicate', kind: 'entity', subjectKey: 'a', entityType: 'product', entityName: 'A' }, { proposalId: 'duplicate', kind: 'claim', subjectKey: 'product', claimType: 'fact', statement: 'Duplicate must not persist', sourceCandidateIds: ['evidence-s1'] }, validClaim('good')]; const x = await directGateRun(proposals); try { assert.equal(x.result.status, 'completed'); const m = x.result.modules.find((v) => v.module === 'company_mapping'); assert.equal(m?.status, 'unavailable'); assert.match(m?.gaps[0]?.reason ?? '', /duplicate local ID/i); assert.equal(x.result.claimRefs.duplicate, undefined); await assertNoCanonicalSemantics(x, [/Duplicate must not persist/, /\"name\":\"A\"/]) } finally { await cleanup(x) } })

test('Workflow direct durable gate rejects conflicting Entity local subject keys as a whole', async () => { const proposals = [{ proposalId: 'a1', kind: 'entity', subjectKey: 'shared', entityType: 'product', entityName: 'A' }, { proposalId: 'a2', kind: 'entity', subjectKey: 'shared', entityType: 'technology', entityName: 'B' }, ...baseEntities(), validClaim('good')]; const x = await directGateRun(proposals); try { assert.equal(x.result.status, 'completed'); assert.match(x.result.diagnostics.join('\n'), /Conflicting Entity local key rejected as a whole: shared/); assert.ok(x.result.entityRefs.product); assert.ok(x.result.claimRefs.good); await assertNoCanonicalSemantics(x, [/\"name\":\"A\"/, /\"name\":\"B\"/]) } finally { await cleanup(x) } })

test('Workflow direct durable gate rejects reserved Industry root redefinition and preserves Workflow root', async () => { const proposals = [{ proposalId: 'root-redefinition', kind: 'entity', subjectKey: 'industry', entityType: 'company', entityName: 'Model Replacement' }, { proposalId: 'product', kind: 'entity', subjectKey: 'product', entityType: 'product', entityName: 'Fixture Product' }, validClaim('good')]; const x = await directGateRun(proposals); try { assert.equal(x.result.status, 'completed'); assert.match(x.result.diagnostics.join('\n'), /Reserved industry root redefinition rejected/); assert.equal(x.result.entityRefs.industry, 'entity:industry-fixture-industry'); assert.ok(x.result.claimRefs.good); const values = await canonicalValues(x.root); assert.equal(values.filter((v) => v.id === 'entity:industry-fixture-industry').length, 1); assert.equal(values.some((v) => v.name === 'Model Replacement'), false) } finally { await cleanup(x) } })

test('Workflow direct durable gate rejects dangling Relation source endpoint', async () => { const proposals = [...baseEntities(), { proposalId: 'dangling-source', kind: 'relation', subjectKey: 'missing', targetKey: 'product', relationType: 'offers_product', sourceCandidateIds: ['evidence-s1'] }, validClaim('good')]; const x = await directGateRun(proposals); try { assert.equal(x.result.status, 'completed'); assert.match(x.result.diagnostics.join('\n'), /Relation rejected: dangling-source/); assert.equal(x.result.relationRefs['dangling-source'], undefined); assert.ok(x.result.claimRefs.good); await assertNoCanonicalSemantics(x, [/dangling-source/]) } finally { await cleanup(x) } })

