test('Workflow clears mandatory Industry Definition with normal authoritative MIIT evidence', async () => {
  const baseExecutor = exec()
  const x = await fixtureRun({ target: { name: 'PCB Manufacturing', aliases: ['Printed Circuit Board'] }, acquisitionWave: async ({ wave }) => wave === 1 ? [miitDefinitionSource] : [], reasoningExecutor: { capabilities: baseExecutor.capabilities, execute: async (r) => { const result = await baseExecutor.execute(r); if (!['industry_module_analysis', 'industry_cross_module_synthesis'].includes(String(r.operation))) return result; const ids = ((r.input as { evidence: Array<{ evidenceId: string }> }).evidence ?? []).map((e) => e.evidenceId); return { ...result, output: { ...(result.output as any), evidenceIds: ids, reportMaterial: { ...((result.output as any).reportMaterial), evidenceIds: ids } } } } } })
  try {
    assert.equal(x.result.status, 'completed', x.result.errors.join('; '))
    const definition = x.result.modules.find((m) => m.module === 'industry_definition')
    assert.equal(definition?.status, 'supported')
    assert.deepEqual(definition?.evidenceIds, ['evidence-miit-definition-anchor'])
    assert.equal(x.result.gatewaySubmitCount, 1)
    assert.ok(x.result.report)
    assert.equal(JSON.parse(await readFile(`${x.result.report!.outputPath}.json`, 'utf8')).sections.length, 16)
    assert.ok(x.result.knowledgeBaseRevision <= 1)
    assert.equal(validateKnowledgeV04Objects(await canonicalValues(x.root) as any).status, 'passed')
  } finally { await cleanup(x) }
})
